import React, { createContext, useContext, useEffect, useState } from 'react';
import api from '../config/api';

const CompanyContext = createContext(null);

export const CompanyProvider = ({ children }) => {
  const [company, setCompany] = useState({
    name: 'Vertix Solutions',
    tagline: 'Turning Ideas Into Powerful Digital Solutions.',
    email: 'hello@vertixsolutions.com',
    phone: '+91 98765 43210',
    address: 'Ahmedabad, Gujarat, India',
    social_links: {
      facebook: '#',
      twitter: '#',
      linkedin: '#',
      instagram: '#',
    },
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api
      .get('/api/company-settings')
      .then((r) => {
        if (r.data) setCompany((prev) => ({ ...prev, ...r.data }));
      })
      .catch(() => {
        // Use default values if API is unavailable
      })
      .finally(() => setLoading(false));
  }, []);

  return (
    <CompanyContext.Provider value={{ company, loading }}>
      {children}
    </CompanyContext.Provider>
  );
};

export const useCompany = () => useContext(CompanyContext);
